Ltac keeps_munch RT AF Sg fr usp L K :=
  lazymatch goal with MUx : munch _ ?ma ?mb |- _ => lazymatch goal with Ax : ART RT ?S4 ma |- _ =>
    let FRS4 := fresh "FRS4" in
    assert (FRS4 : rt_frames RT S4 = (fr, 2%nat) :: rt_frames RT Sg) by (repeat match goal with H : rt_frames _ _ = _ |- _ => rewrite H end; reflexivity);
    assert (K : keeps_live L ma mb)
      by (let bb := fresh "bb" in let kk := fresh "kk" in let Hin := fresh "Hin" in let aa := fresh "aa" in let Haa := fresh "Haa" in let Hin4 := fresh "Hin4" in
          intros bb kk Hin aa Haa; apply MUx;
          assert (Hin4 : In (bb, kk) (rt_live RT S4))
            by (first [exact Hin | revert Hin; repeat match goal with H : rt_live RT _ = rt_live RT _ |- _ => rewrite H end; first [exact (fun h => h) | live_sub_tac]]);
          let LR0 := fresh "LR0" in let LR1 := fresh "LR1" in let LR2 := fresh "LR2" in let D1 := fresh "D1" in let D2 := fresh "D2" in
          pose proof (af_live_range RT AF S4 ma bb kk Ax Hin4) as (LR0 & LR1 & LR2);
          pose proof (af_frames_range RT AF S4 ma fr 2%nat Ax ltac:(rewrite FRS4; left; reflexivity)) as (_ & _ & _ & D1); specialize (D1 bb kk Hin4);
          pose proof (af_fshadow_apart RT AF S4 ma fr 2%nat Ax ltac:(rewrite FRS4; left; reflexivity)) as (D2 & _); specialize (D2 bb kk Hin4);
          change (fs_size 2%nat) with 256 in D1, D2; unfold shad, SHB in D2;
          repeat match goal with H : rt_sp0 RT _ = _ |- _ => rewrite H in LR1 end; unfold STACK_WIN, USTACK_TOP, RT_STACK, SEGTOP_A in LR1, LR2;
          cbn [outside]; repeat match goal with H : rt_sp0 RT Sg - _ <= _ |- _ => revert H end; repeat match goal with H : _ + (65536 + _) <= usp |- _ => revert H end;
          clear - LR0 LR1 LR2 D1 D2 Haa; intros; repeat split; try exact I; first [lia | Z.div_mod_to_equations; lia]);
    clear FRS4 end end.

(* [comment removed for export] *)
Ltac keeps_callF RT AF Sg fr L K :=
  lazymatch goal with AGx : agree_on (fun a => aclient (rt_live RT ?S5) ?frs ?spx a /\ outside ?W a) ?m1 ?m2 |- _ =>
  lazymatch goal with Ax : ART RT ?S4 m1 |- _ =>
    let FRS4 := fresh "FRS4" in
    assert (FRS4 : rt_frames RT S4 = (fr, 2%nat) :: rt_frames RT Sg) by (repeat match goal with H : rt_frames _ _ = _ |- _ => rewrite H end; reflexivity);
    assert (K : keeps_live L m1 m2)
      by (apply (keeps_live_of_agree _ _ _ _ m1 m2 _ AGx);
          [ solve [live_sub_tac]
          | let bb := fresh "bb" in let kk := fresh "kk" in let xx := fresh "xx" in let Hin := fresh "Hin" in let Hxx := fresh "Hxx" in let D1 := fresh "D1" in
            let Hin4 := fresh "Hin4" in
            intros bb kk xx Hin Hxx;
            assert (Hin4 : In (bb, kk) (rt_live RT S4))
              by (first [exact Hin | revert Hin; repeat match goal with H : rt_live RT _ = _ |- _ => rewrite H end; first [exact (fun h => h) | live_sub_tac]]);
            pose proof (af_frames_range RT AF S4 m1 fr 2%nat Ax ltac:(rewrite FRS4; left; reflexivity)) as (_ & _ & _ & D1);
            specialize (D1 bb kk Hin4); change (fs_size 2%nat) with 256 in D1;
            cbn [outside]; clear - D1 Hxx; repeat split; try exact I; lia ]);
    clear FRS4 end end.

(* [comment removed for export] *)
Ltac keeps_callH RT AF L hd K :=
  lazymatch goal with AGx : agree_on (fun a => aclient (rt_live RT ?S5) ?frs ?spx a /\ outside ?W a) ?m1 ?m2 |- _ =>
  lazymatch goal with Ax : ART RT S5 m1 |- _ =>
    assert (K : keeps_live L m1 m2);
    [ apply (keeps_live_of_agree _ _ _ _ m1 m2 _ AGx);
      [ | let bb := fresh "bb" in let kk := fresh "kk" in let xx := fresh "xx" in let Hin := fresh "Hin" in let Hxx := fresh "Hxx" in let AP := fresh "AP" in
          intros bb kk xx Hin Hxx;
          assert (AP : bb + kk <= hd \/ hd + 64 <= bb); [ apply (live_apart2 RT AF S5 m1 bb kk hd 64 Ax) | cbn [outside]; clear - AP Hxx; repeat split; try exact I; lia ] ]
    | ] end end.

Ltac livn := repeat match goal with H : rt_live _ _ = rt_live _ _ |- _ => rewrite H end.

(* [comment removed for export] *)
Ltac split_rows H := lazymatch type of H with
  | Forall _ (_ :: _) => let T := fresh "TR" in pose proof (Forall_inv H) as T; cbn [fst snd po_row app] in T;
                        let H2 := fresh "RW" in pose proof (Forall_inv_tail H) as H2; clear H; split_rows H2
  | _ => clear H end.

(* [comment removed for export] *)
Ltac mk_ucx m usp bsp s0 us0 ura ras UCTX ES0 ERA SPA SPT UCX :=
  let RA4096 := fresh "RA4096" in
  assert (RA4096 : 4096 <= ura < 2^64) by (first [assumption | split; assumption]);
  lazymatch goal with AG : agree_on ?PFx m ?mc, FRx : rw_cells asegs ?mc bsp _ |- _ =>
    let UCTXc := fresh "UCTXc" in let FRc := fresh "FRc" in let REC := fresh "REC" in
    assert (UCTXc : chain_ok mc usp us0 ras)
      by (apply (chain_ok_keep ras m mc usp us0 UCTX); eapply agree_sub; [exact AG|]; cbv beta; intros zz Hzz; left; exact Hzz);
    pose proof FRx as FRc; split_before FRc (C8 s0) REC; clear FRc; rewrite ES0, ERA in REC;
    assert (UCX : chain_ok mc bsp usp (ura :: ras))
      by (apply (chain_ok_push mc bsp usp ura us0 ras);
          [clear; lia| clear - SPA; Z.div_mod_to_equations; lia| unfold USTACK_TOP; clear - SPT; lia| exact RA4096
          | unfold us0; apply bv_unsigned_in_range| exact REC| exact UCTXc]);
    clear REC UCTXc RA4096 end.

